#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 31

char s[MAX_SIZE];
int s_len;
int n;

/*!
 * 全排列求解
 * @param pre 排列最后一个字符在cArr中的位置
 * @param level 排列的长度
 * @param used used[i] 用于标记 s[i] 元素是否已使用
 * @param count 符号要求的排列有几个
 * @return count
 */
int dfs(int pre, int level, int used[], int count) {
    // 当排列长度到达n，则是一个符合要求的排列
    if (level == n) {
        // 符合要求的排列个数+1
        return ++count;
    }

    for (int i = 0; i < s_len; i++) {
        // 每个字符只能用一次
        if (used[i]) continue;

        // 相同的字符不能相邻， pre指向前面一个被选择的字符的在s中的位置，i指向当前被选择的字符在s中的位置
        if (pre >= 0 && s[i] == s[pre]) continue;

        // 树层去重(去除重复排列)
        if (i > 0 && s[i] == s[i - 1] && !used[i - 1]) continue;

        used[i] = 1;
        count = dfs(i, level + 1, used, count);
        used[i] = 0;
    }

    return count;
}

int cmp(const void *a, const void *b) {
    return *((char *) a) - *((char *) b);
}

int getResult() {
    int i = 0;
    while (s[i] != '\0') {
        // 输入非法
        if (s[i] < 'a' || s[i] > 'z') return 0;
        i++;
    }

    s_len = i;

    if (s_len < n) {
        // 无法拼接出满足条件的字符串
        return 0;
    }

    // 排序s，可以方便后面求解全排列时，进行树层去重
    qsort(s, i, sizeof(char), cmp);

    int used[MAX_SIZE] = {0};
    return dfs(-1, 0, used, 0);
}

int main() {
    scanf("%s", s);
    scanf("%d", &n);

    printf("%d\n", getResult());

    return 0;
}
